<?php require_once 'includes/db.php'; $pageTitle='Endereços'; require 'includes/header.php'; $rows=$pdo->query('SELECT * FROM enderecos ORDER BY id DESC')->fetchAll(); ?><div class="page-heading"><div><h1 class="h3 mb-1">Endereços</h1><p class="text-secondary mb-0">Gerencie locais de coleta e entrega.</p></div><a class="btn btn-primary" href="endereco_form.php">+ Cadastrar endereço</a></div><div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Identificação</th><th>Logradouro</th><th>Cidade/UF</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['identificacao'])?></td><td><?=e($r['logradouro'].', '.$r['numero'])?></td><td><?=e($r['cidade'].'/'.$r['estado'])?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="endereco_form.php?id=<?=$r['id']?>">Editar</a> <a class="btn btn-sm btn-outline-danger" onclick="return confirm('Excluir endereço?')" href="delete.php?tipo=endereco&id=<?=$r['id']?>">Excluir</a></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="4" class="text-center text-secondary">Nenhum endereço cadastrado.</td></tr><?php endif; ?></tbody></table></div></div><?php require 'includes/footer.php'; ?>
